  ?singer vns:age ?age .
  ?singer vns:song_release_year ?releaseYear .
  FILTER(?age = (SELECT MIN(?minAge) WHERE {
    ?singer2 vns:age ?minAge .
  }))
}

SELECT ?country (COUNT(?singer) AS ?num_singers)
