PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX ex: <http://example.org/>

SELECT DISTINCT ?songName
WHERE {
  # Calculate the total number of singers, total age, and total capacity
  VALUES ?totalCapacity { (SELECT (SUM(?capacity) as ?sum) WHERE {
    ?stadium rdf:type ex:stadium ;
           ex:stadium_id ?id ;
           ex:capacity ?capacity .
    BIND(COUNT(?stadium) as ?totalStadiums)
  }) }
  VALUES ?totalAge { (SELECT (SUM(?age) as ?sum) WHERE {
    ?singer rdf:type ex:singer ;
           ex:singer_id ?id ;
           ex:age ?age .
    BIND(COUNT(?singer) as ?totalSingers)
  }) }
  # Calculate the average age
  BIND((?totalAge / ?totalSingers) as ?averageAge)

  # Filter singers above the average age and find their song names
  ?singer rdf:type ex:singer ;
         ex:singer_id ?id ;
         ex:age ?age .
  FILTER(?age > ?averageAge)
  ?singer_in_concert rdf:type ex:singer_in_concert ;
                      ex:concert_id ?concertId ;
                      ex:singer_id ?singerId .
  OPTIONAL { ?singer_in_concert ex:song_name ?songName }
  BIND(CONCAT("", ?songName) as ?songName)
}
ORDER BY ?songName

